mapper.select:
SELECT s.*, c.name as className, m.name as majorName, cl.name as collegeName FROM student s LEFT JOIN class_info c ON s.class_id = c.id AND c.deleted = 0 LEFT JOIN major m ON s.major_id = m.id AND m.deleted = 0 LEFT JOIN college cl ON s.college_id = cl.id AND cl.deleted = 0 WHERE s.deleted = 0
AND s.student_no LIKE CONCAT('%', #{params.studentNo}, '%')
AND s.name LIKE CONCAT('%', #{params.name}, '%')
AND s.college_id = #{params.collegeId}
AND s.grade = #{params.grade}
ORDER BY s.create_time DESC
